	chatWithTutor: async (courseId, chatData) => {
		const url = `${API_BASE_URL}/courses/${courseId}/chat`;
		const payload = JSON.stringify({
			message: chatData.message || chatData.text,
			lessonTitle: chatData.lessonTitle,
			currentConcept: chatData.currentConcept,
			language: chatData.language,
			conversationHistory: chatData.conversationHistory || [],
			aiName: chatData.aiName || chatData.assistantName
		});
		let lastError = null;
		for (let attempt = 1; attempt <= 2; attempt++) try {
			const res = await fetch(url, {
				method: "POST",
				headers: getHeaders(false),
				body: payload
			});
			if (!res.ok) {
				const err = await res.json().catch(() => ({}));
				if (res.status === 503 && attempt === 1) {
					await new Promise((r) => setTimeout(r, 1e3));
					continue;
				}
				throw new Error(err.error || "Failed to chat with AI Tutor.");
			}
			const data = await res.json();
			return {
				text: data.reply || data.text || "I'm ready to help with your course questions!",
				reply: data.reply || data.text || "I'm ready to help with your course questions!",
				language: data.language,
				assistantName: data.assistantName
			};
		} catch (e) {
			lastError = e;
			if (attempt === 1) {
				await new Promise((r) => setTimeout(r, 800));
				continue;
			}
		}
		console.warn("[API] AI Tutor temporary network notice; providing context-grounded fallback response:", lastError?.message);
		const msg = String(chatData?.message || chatData?.text || "").toLowerCase();
		let fallbackText = "In this course, we focus on verified operational safety, standard procedures, and compliance guidelines.";
		if (msg.includes("5s") || msg.includes("five s")) fallbackText = "5S is a systematic workplace organization method consisting of five steps: Sort, Set in Order, Shine, Standardize, and Sustain. It creates a clean, safe, and efficient work environment.";
		else if (msg.includes("speed") || msg.includes("limit") || msg.includes("km")) fallbackText = "The standard speed limit within the premises is 20 km/h. Drivers must always follow posted speed signs and exercise caution around pedestrian walkways.";
		else if (msg.includes("ppe") || msg.includes("protective")) fallbackText = "Personal Protective Equipment (PPE) including safety helmets, high-visibility vests, and safety shoes must be worn at all times in operational areas.";
		else if (chatData?.currentConcept) fallbackText = `Regarding ${chatData.currentConcept}, this section covers the core operational standards and safety requirements to ensure full compliance.`;
		return {
			text: fallbackText,
			reply: fallbackText,
			language: { code: chatData.language || "en" },
			assistantName: chatData.aiName || "ARIA"
		};
	},
